/* W205: measure the real glibc heap at the vulnerable allocation, with no
 * planted victim and no forced layout. malloc/free are wrapped only to
 * record live allocations; the pinned source gets a 3-line hook in
 * setup_malloc() (generated by run-neighbor.sh) that calls w205_watch8() on
 * every 8-byte allocation. The 4th such allocation in this PoC is
 * c->multiplicands (count8=4 observed); at that instant we print all live
 * allocations overlapping the 30-word OOB run [p+8, p+128).
 * No wrapped pointer is called. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_LIVE 4096
#define TARGET_INDEX 4
struct alloc {
    void *p;
    size_t sz;
    unsigned long seq;
    int live;
};
static struct alloc live[MAX_LIVE];
static int live_n = 0;
static unsigned long alloc_seq = 0;
static int count8 = 0;

static void *guard_malloc(size_t sz)
{
    void *p = malloc(sz);
    if (p && live_n < MAX_LIVE) {
        live[live_n].p = p;
        live[live_n].sz = sz;
        live[live_n].seq = ++alloc_seq;
        live[live_n].live = 1;
        ++live_n;
    }
    return p;
}

static void guard_free(void *p)
{
    int i;
    for (i = 0; i < live_n; ++i)
        if (live[i].p == p && live[i].live) { live[i].live = 0; break; }
    free(p);
}

#define malloc guard_malloc
#define free guard_free
#define STB_VORBIS_IMPLEMENTATION
#include "stb_vorbis.c"

void w205_watch8(void *p, size_t sz)
{
    int i;
    uintptr_t base, end;
    (void) sz;
    ++count8;
    if (count8 != TARGET_INDEX) return;
    base = (uintptr_t) p;
    end = base + 128;
    printf("watch=%p index=%d range=[%p..%p]\n", p, count8,
           (void *) base, (void *) end);
    for (i = 0; i < live_n; ++i) {
        if (!live[i].live) continue;
        printf("live seq=%lu addr=%p size=%lu delta=%ld\n",
               live[i].seq, live[i].p, (unsigned long) live[i].sz,
               (long)((uintptr_t) live[i].p - base));
    }
    for (i = 0; i < live_n; ++i) {
        uintptr_t a, b;
        if (!live[i].live || live[i].p == p) continue;
        a = (uintptr_t) live[i].p;
        b = a + live[i].sz;
        if (b > base && a < end)
            printf("overlap seq=%lu addr=%p size=%lu delta=%ld\n",
                   live[i].seq, live[i].p, (unsigned long) live[i].sz,
                   (long)(a - base));
    }
    printf("snapshot_live=%d count8=%d\n", live_n, count8);
    fflush(stdout);
}

int main(int argc, char **argv)
{
    FILE *fp;
    long n;
    int err = 0;
    unsigned char *buf;
    stb_vorbis *v;
    setvbuf(stdout, NULL, _IONBF, 0);
    if (argc != 2) { fprintf(stderr, "usage: %s file.ogg\n", argv[0]); return 2; }
    fp = fopen(argv[1], "rb");
    if (!fp) { perror("fopen"); return 2; }
    if (fseek(fp, 0, SEEK_END) != 0) return 2;
    n = ftell(fp);
    if (n < 0 || n > 1000000) return 2;
    rewind(fp);
    buf = (unsigned char *) malloc((size_t) n);
    if (!buf || fread(buf, 1, (size_t) n, fp) != (size_t) n) return 2;
    fclose(fp);
    v = stb_vorbis_open_memory(buf, (int) n, &err, NULL);
    printf("open_memory=%p err=%d bytes=%ld count8=%d\n",
           (void *) v, err, n, count8);
    if (v) stb_vorbis_close(v);
    free(buf);
    return 0;
}
